mapper.select:
SELECT allocation_goal_id, job_id, target_month, recommend_hour
FROM ALLOCATION_GOAL
WHERE allocation_goal_id = #{allocationGoalId}

SELECT ag.allocation_goal_id, ag.job_id, ag.target_month, ag.recommend_hour
FROM ALLOCATION_GOAL ag
INNER JOIN JOB j ON j.job_id = ag.job_id
WHERE j.user_id = #{userId}
AND ag.target_month = #{targetMonth}
ORDER BY ag.job_id

mapper.delete:
DELETE ag
FROM ALLOCATION_GOAL ag
INNER JOIN JOB j ON j.job_id = ag.job_id
WHERE j.user_id = #{userId}
AND ag.target_month = #{targetMonth}

